let page='dashboard',selectedUnit=units.find(u=>u.role!=='admin').id,selectedGroup='g1',search='',filter='all',chatOther='admin',chatMessages=[],drawer=false,editState=null,chatSearch='',dashboardGroup='all',reviewGroup='all',accountGroup='all';
