function login(){store.user=null;const last=localStorage.getItem('dt2026-last-unit')||'admin';$('#app').innerHTML=`<div class="login"><section class="login-story">${brand()}<div class="login-story-body"><span class="season-tag">KHÔNG GIAN THI ĐUA · 2026</span><h1>Mỗi minh chứng.<br>Một dấu ấn<br><em>tuổi trẻ Đồng Tháp.</em></h1><p>Nơi các đơn vị cùng ghi nhận kết quả, hoàn thiện hồ sơ và lan tỏa những hoạt động có ý nghĩa.</p>${lotus}<div class="login-facts"><div><strong>113</strong><span>đơn vị tham gia</span></div><div><strong>05</strong><span>bộ tiêu chí</span></div><div><strong>2026</strong><span>năm thi đua</span></div></div></div><div class="login-story-footer">TỈNH ĐOÀN ĐỒNG THÁP <span>ĐẤT SEN HỒNG</span></div></section><section class="login-form-panel"><form class="login-card" id="login"><span class="form-icon">${logo()}</span><div class="eyebrow">CHÀO MỪNG BẠN TRỞ LẠI</div><h2>Đăng nhập hệ thống</h2><p class="subtitle">Hệ thống minh chứng thi đua tỉnh Đoàn Đồng Tháp năm 2026</p>${store.demo?'<div class="notice info">Bản trải nghiệm · Dữ liệu được lưu trên trình duyệt.</div>':''}<div class="field"><label for="login-unit">Đơn vị của bạn</label><select id="login-unit">${options(units,'name',last)}</select></div><div class="field"><label for="password">Mật khẩu</label><div class="password-wrap"><input id="password" type="password" autocomplete="current-password" placeholder="Nhập mật khẩu" ${store.demo?'disabled':''}><button type="button" id="toggle-password" aria-label="Hiện mật khẩu">Hiện</button></div></div><button class="btn primary login-submit" ${store.demo?'disabled':''}>Đăng nhập ${icon('arrow',18)}</button>${store.demo?'<button type="button" id="demo" class="btn">Trải nghiệm tài khoản đã chọn</button>':''}<div class="login-security">${icon('shield',15)}Tài khoản do Tỉnh Đoàn cấp · Bảo vệ theo quyền đơn vị</div><p class="login-assistance">Cần hỗ trợ đăng nhập? Liên hệ quản trị viên Tỉnh Đoàn.</p></form><small class="login-copyright">© 2026 Tỉnh Đoàn Đồng Tháp ${releaseSummary()}</small></section></div>`;$('#login').onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;try{localStorage.setItem('dt2026-last-unit',$('#login-unit').value);await store.login($('#login-unit').value,$('#password').value)}catch(x){err(x)}finally{b.disabled=false}};$('#toggle-password').onclick=()=>{const input=$('#password'),show=input.type==='password';input.type=show?'text':'password';$('#toggle-password').textContent=show?'Ẩn':'Hiện';$('#toggle-password').setAttribute('aria-label',show?'Ẩn mật khẩu':'Hiện mật khẩu')};$('#demo')?.addEventListener('click',()=>{store.loadDemo();store.user={...units.find(u=>u.id===$('#login-unit').value)};selectedUnit=admin()?units.find(u=>u.role!=='admin').id:store.user.id;render()});}
function navigation(){const list=[['dashboard','grid'],['criteria','file'],...(admin()?[['review','check']]:[]),['ranking','trophy'],['chat','chat']];return `<aside class="sidebar ${drawer?'open':''}">${brand()}<div class="nav-label">KHÔNG GIAN LÀM VIỆC</div>${list.map(([id,ic])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}">${icon(ic)}${titles[id]}${id==='review'?`<span class="count">${activeRecords().filter(r=>r.status==='submitted').length}</span>`:''}</button>`).join('')}<div class="nav-label">QUẢN TRỊ & HỖ TRỢ</div>${[...(admin()?[['manageCriteria','file'],['accounts','users'],['audit','clock'],['settings','settings']]:[]),['explanations','check'],['help','help']].map(([id,ic])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}">${icon(ic)}${titles[id]}${id==='explanations'&&admin()&&Object.values(store.explanations).some(r=>r.status==='pending')?`<span class="count">${Object.values(store.explanations).filter(r=>r.status==='pending').length}</span>`:''}</button>`).join('')}${!admin()?`<button class="nav-item" data-action="change-password">${icon('shield')}Đổi mật khẩu</button>`:''}<div class="side-bottom"><div class="year-card initiative-card"><p><em>Phần mềm là công trình sáng kiến cấp cơ sở của Tỉnh đoàn Đồng Tháp (Tác giả: Phúc Minh, Phước Thịnh, Trung Thành).</em></p></div><div class="side-footer"><div class="avatar">${admin()?'QT':'ĐV'}</div><div style="flex:1;min-width:0"><strong style="font-size:11px">${admin()?'Quản trị Tỉnh Đoàn':e(store.user.name)}</strong><div class="status-line">${store.demo?'Phiên trải nghiệm':'Tài khoản đã xác thực'}</div></div><button class="icon-btn" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">${icon('logout',17)}</button></div></div></aside>`}
function render(preserve=false){syncCatalog();if(!store.user)return login();if(!admin()&&['review','accounts','settings','audit','manageCriteria'].includes(page))page='dashboard';const active=document.activeElement,focusId=preserve?active?.id:null,caret=active?.selectionStart,values=preserve?all('#app input,#app textarea,#app select').map(x=>[x.id,x.value,x.checked]):[];$('#app').innerHTML=`${drawer?'<button class="nav-backdrop" data-action="close-menu" aria-label="Đóng danh mục"></button>':''}${navigation()}<main class="main"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Mở danh mục">${icon('menu')}</button><span>Không gian thi đua</span><span class="crumb-separator">/</span><strong>${titles[page]}</strong></div><div class="top-actions"><button class="command-search" data-action="quick-search" aria-label="Tìm nhanh đơn vị hoặc điều kiện">${icon('search',17)}<span>Tìm nhanh</span><kbd>Ctrl K</kbd></button><span class="pill ${store.demo||!store.synced?'warn':''}"><span class="dot"></span>${store.demo?'Trải nghiệm':store.synced?'Đã đồng bộ':'Đang đồng bộ'}</span><button class="icon-btn notification-btn" data-action="notifications" aria-label="Công việc cần xử lý">${icon('bell')}${activeRecords().some(r=>r.status===(admin()?'submitted':'returned')&&(admin()||r.unitId===store.user.id))?'<i></i>':''}</button><div class="avatar top-avatar">${admin()?'QT':'ĐV'}</div></div></header><div class="content">${store.demo?'<div class="notice info">Dữ liệu trải nghiệm trên trình duyệt này.</div>':''}${store.settings.resetInProgress?'<div class="notice">Đang đặt lại số liệu. Các thao tác nộp và chấm hồ sơ đang tạm khóa.</div>':''}${({dashboard,criteria,review,ranking,chat,accounts,settings,help,audit,manageCriteria,explanations})[page]()}</div><footer class="app-footer"><span>Tỉnh Đoàn Đồng Tháp · Thi đua năm 2026 ${releaseSummary()}</span><span>${store.demo?'Phiên trải nghiệm':store.lastSync?'Đồng bộ gần nhất '+fmtDate(store.lastSync):'Kết nối dữ liệu chung'}</span></footer></main>`;bind();for(const [id,value,checked] of values){const el=document.getElementById(id);if(el){el.value=value;if(el.type==='checkbox')el.checked=checked}}if(focusId){const el=document.getElementById(focusId);el?.focus();if(typeof caret==='number'&&['text','search','password'].includes(el?.type))el.setSelectionRange(caret,caret)}if(page==='chat'){renderMessages();filterContacts();}}
function head(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">TỈNH ĐOÀN ĐỒNG THÁP · 2026</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="buttonrow">${actions}</div></div>`}
function exportBtn(){return `<button class="btn" data-action="export">${icon('download',16)}Xuất Excel</button>`}
function dashboard(){const allUnits=units.filter(u=>u.role!=='admin'),us=admin()?allUnits.filter(u=>dashboardGroup==='all'||u.group===dashboardGroup):allUnits.filter(u=>u.id===store.user.id),ms=us.map(u=>metrics(u,sets,store.records)),sum=k=>ms.reduce((n,m)=>n+m[k],0),total=sum('total'),approved=sum('approved'),submitted=sum('submitted'),returned=sum('returned'),draft=sum('draft'),done=approved+submitted,pct=total?Math.round(100*done/total):0,scope=admin()?(dashboardGroup==='all'?'Toàn tỉnh':sets.find(x=>x.id===dashboardGroup)?.name):store.user.name,ordered=[...us].sort((a,b)=>metrics(b,sets,store.records).returned-metrics(a,sets,store.records).returned||metrics(a,sets,store.records).progress-metrics(b,sets,store.records).progress);return `${head(admin()?'Tổng quan điều hành':'Không gian của đơn vị',admin()?'Tiến độ, công việc cần xử lý và kết quả thi đua trong cùng một màn hình.':'Theo dõi hồ sơ, hoàn thiện minh chứng và cập nhật phản hồi từ Tỉnh Đoàn.',exportBtn())}<div class="overview-banner"><div><span class="season-tag">ĐỢT ĐÁNH GIÁ NĂM 2026</span><h2>${admin()?'Theo dõi từng bước tiến.':'Sẵn sàng ghi nhận những dấu ấn.'}</h2><p>${admin()?'Quản lý hồ sơ minh chứng của '+allUnits.length+' đơn vị trên toàn tỉnh.':e(store.user.name)+' · '+(setFor(store.user)?.name||'Chưa gán bộ tiêu chí')}</p><div class="banner-tags"><span>${icon('shield',14)}${store.settings.locked?'Đợt nộp đang khóa':'Đợt nộp đang mở'}</span><span>${icon('clock',14)}${store.settings.deadline?'Hạn nộp '+e(store.settings.deadline.replace('T',' · ')):'Chưa đặt hạn nộp'}</span></div></div><div class="banner-art">${lotus}<span class="banner-year">2026</span></div></div>${admin()?`<div class="scope-tabs" role="group" aria-label="Phạm vi tổng quan"><button data-overview="all" class="${dashboardGroup==='all'?'active':''}">Toàn tỉnh</button>${sets.map(s=>`<button data-overview="${s.id}" class="${dashboardGroup===s.id?'active':''}">${e(s.name)}</button>`).join('')}</div>`:''}<div class="stats">${[[num(total),'Điều kiện cần thực hiện','file',`${us.length} đơn vị · ${num(draft)} bản nháp`,'criteria'],[num(done),'Đã gửi minh chứng','upload',`${pct}% trên tổng số điều kiện`,'criteria'],[num(submitted),'Hồ sơ chờ duyệt','clock',admin()?'Sẵn sàng để kiểm tra và chấm điểm':'Đang chờ Tỉnh Đoàn đánh giá',admin()?'review':'criteria'],[num(approved),'Điều kiện đã chấm','check',`${num(returned)} hồ sơ cần bổ sung`,admin()?'review':'criteria']].map(([v,l,ic,n,target])=>`<button class="stat" data-page="${target}"><div class="stat-top"><span>${l}</span><span class="stat-icon">${icon(ic,20)}</span></div><div class="stat-value">${v}</div><div class="stat-note">${n}</div></button>`).join('')}</div><div class="action-grid"><button class="action-tile" data-page="${admin()?'review':'criteria'}"><span class="action-icon">${icon(admin()?'check':'file',22)}</span><span><strong>${admin()?'Duyệt hồ sơ':'Hoàn thiện minh chứng'}</strong><small>${admin()?num(submitted)+' hồ sơ trong phạm vi đang chờ':num(returned)+' hồ sơ cần bổ sung'}</small></span>${icon('arrow',18)}</button><button class="action-tile" data-action="export"><span class="action-icon gold">${icon('download',22)}</span><span><strong>Báo cáo thi đua</strong><small>Xuất tổng hợp và hồ sơ chi tiết</small></span>${icon('arrow',18)}</button><button class="action-tile" data-page="chat"><span class="action-icon blue">${icon('chat',22)}</span><span><strong>Trao đổi trực tiếp</strong><small>Kết nối với Tỉnh Đoàn và các đơn vị</small></span>${icon('arrow',18)}</button></div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Tiến độ hoàn thiện</h2><small>${e(scope)} · ${num(total)} điều kiện</small></div><span class="pill">${pct}% đã gửi</span></div><div class="card-body"><div class="progress-chart"><div class="donut" style="--pct:${pct}%"><div class="donut-label"><strong>${pct}%</strong><span>tiến độ gửi</span></div></div><div class="legend">${[['#0066cc','Đã chấm điểm',approved],['#d8a953','Chờ duyệt',submitted],['#bd6b61','Cần bổ sung',returned],['#dce1e6','Chưa gửi',total-done-returned]].map(([c,l,v])=>`<div class="legend-row"><i class="swatch" style="background:${c}"></i>${l}<strong>${num(v)}</strong></div>`).join('')}</div></div><div class="chart-foot">${icon('help',15)}Tính theo số điều kiện đã gửi hoặc đã chấm.</div></div></section><section class="card"><div class="card-head"><div><h2>${admin()?'Tiến độ các khối':'Kết quả của đơn vị'}</h2><small>${admin()?'So sánh tỷ lệ hoàn thiện theo bộ tiêu chí':'Chỉ ghi nhận điểm sau khi được duyệt'}</small></div>${icon('building',20)}</div><div class="card-body group-bars">${admin()?sets.map((s,i)=>{const group=allUnits.filter(u=>u.group===s.id),m=group.map(u=>metrics(u,sets,store.records)),d=m.reduce((a,v)=>a+v.done,0),t=m.reduce((a,v)=>a+v.total,0),p=t?Math.round(d/t*100):0;return `<button class="group-bar" data-overview="${s.id}"><div class="bar-label"><span><i class="group-dot group-${i}"></i>${e(s.name)}</span><strong>${p}%</strong></div><div class="track"><div class="fill" style="width:${p}%"></div></div><small>${group.length} đơn vị · ${num(d)}/${num(t)} điều kiện đã gửi</small></button>`}).join(''):`<div class="score-display"><strong>${approved?num(sum('score')):'—'}</strong><span>/ ${num(sum('max'))} điểm</span><p>${approved?num(approved)+' điều kiện đã được chấm điểm':'Điểm sẽ hiển thị sau khi được duyệt'}</p></div><button class="btn" data-page="criteria">Xem hồ sơ của tôi ${icon('arrow',16)}</button>`}</div></section><section class="card wide"><div class="card-head"><div><h2>${admin()?'Đơn vị cần theo dõi':'Tiến độ hồ sơ của tôi'}</h2><small>${admin()?'Ưu tiên đơn vị có yêu cầu bổ sung hoặc tiến độ thấp':'Theo dõi kết quả và phản hồi trong đợt thi đua'}</small></div><button class="btn small" data-page="ranking">Bảng xếp hạng ${icon('arrow',15)}</button></div>${unitTable(ordered.slice(0,8),false)}<div class="table-footer"><span>${us.length} đơn vị trong phạm vi</span><span>Điểm được cập nhật sau khi duyệt</span></div></section></div>`}
function unitTable(us,ranked=false){return `<div class="table-wrap"><table><thead><tr><th>${ranked?'HẠNG':'STT'}</th><th>ĐƠN VỊ</th><th>TIẾN ĐỘ GỬI</th><th>ĐÃ CHẤM</th><th>ĐIỂM DUYỆT</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${us.map((u,i)=>{const m=metrics(u,sets,store.records);return `<tr><td class="rank">${ranked?(u.rank||'—'):String(i+1).padStart(2,'0')}</td><td><div class="name"><div class="avatar">${icon('building',16)}</div>${e(u.name)}</div></td><td><div class="table-progress"><div class="track"><div class="fill" style="width:${m.progress}%"></div></div><span>${m.progress}%</span></div></td><td>${m.approved}/${m.total}</td><td><strong>${m.approved?num(m.score):'—'}</strong><small> / ${m.max||'—'}</small></td><td>${badge(m.returned?'returned':m.submitted?'submitted':m.approved===m.total&&m.total?'approved':m.approved||m.draft?'Đang thực hiện':'empty')}</td><td><button class="icon-btn" data-unit="${u.id}" aria-label="Xem ${e(u.name)}">${icon('arrow',15)}</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">Không có đơn vị phù hợp.</td></tr>'}</tbody></table></div>`}
function badge(status){return `<span class="badge ${status}">${statuses[status]||status}</span>`}
function discrepancy(s){return ['g4','g5'].includes(s?.id)?`<div class="notice">${icon('help',17)}<span><strong>Cần đối chiếu văn bản nguồn.</strong> ${s.id==='g4'?'Phần tổng hợp ghi 26 điều kiện / 113 điểm, nhưng các dòng chi tiết có 27 điều kiện / 123 điểm.':'Phần tổng hợp ghi 25 điều kiện / 117 điểm, nhưng các dòng chi tiết có 28 điều kiện / 130 điểm.'} Ứng dụng đang giữ đầy đủ từng dòng chi tiết; chưa suy diễn mức xếp loại thi đua.</span></div>`:''}
function criteria(){const u=unit(),s=setFor(u),m=metrics(u,sets,store.records);return `${head('Minh chứng thi đua','Nộp kết quả thực hiện theo từng điều kiện của bộ tiêu chí.',exportBtn())}<div class="filters"><select id="unit-select" aria-label="Đơn vị">${options(units.filter(u=>u.role!=='admin'),'name',selectedUnit)}</select><div class="search">${icon('search',16)}<input id="search" placeholder="Tìm nội dung hoặc mã điều kiện…" value="${e(search)}"></div>${areaSelect()}<select id="status-filter" aria-label="Lọc trạng thái"><option value="all">Tất cả trạng thái</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select></div>${!admin()&&u.id!==store.user.id?'<div class="notice info">Bạn đang xem minh chứng của đơn vị khác. Chỉ đơn vị sở hữu và quản trị viên được chỉnh sửa.</div>':''}${campaignClosed(store.settings)?'<div class="notice">Đã khóa hoặc hết hạn nộp minh chứng. Đơn vị có thể mở từng điều kiện để gửi kiến nghị, giải trình; hồ sơ minh chứng không được sửa.</div>':''}${!s?'<div class="card empty">Đơn vị này chưa có bộ tiêu chí được cung cấp.<br>Vui lòng bổ sung văn bản dành cho Đoàn Thanh niên Quân sự Tỉnh.</div>':`${discrepancy(s)}<div class="card" style="padding:18px 20px;margin-bottom:20px"><div class="bar-label"><strong>${e(s.name)} · ${s.items.length} điều kiện · ${num(m.max)} điểm</strong><span>${m.done}/${m.total} đã gửi</span></div><div class="track"><div class="fill" style="width:${m.progress}%"></div></div><div class="status-line">Nguồn cung cấp: Phần 1 — Các điều kiện bắt buộc. <button class="linkbutton" data-source="${s.id}">Xem nguyên văn</button></div></div><div class="status-tabs" role="group" aria-label="Lọc nhanh điều kiện">${[['all','Tất cả',m.total],['empty','Chưa thực hiện',m.total-m.draft-m.submitted-m.approved-m.returned],['draft','Bản nháp',m.draft],['submitted','Chờ duyệt',m.submitted],['returned','Cần bổ sung',m.returned],['approved','Đã chấm',m.approved]].map(([id,label,count])=>`<button class="${filter===id?'active':''}" data-status-chip="${id}">${label}<span>${count}</span></button>`).join('')}</div>${s.groups.map(g=>{const items=s.items.filter(c=>c.section===g.title&&matchesArea(c)&&(filter==='all'||(rec(u,c)?.status||'empty')===filter)&&`${c.code} ${c.title} ${areaName(c.area)}`.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));return items.length?`<details class="card criteria-group" open><summary class="group-head"><h2>${e(sectionLabel(g.title))}</h2><span class="badge">${items.length} điều kiện</span></summary>${items.map(c=>criterionRow(u,c)).join('')}</details>`:''}).join('')||'<div class="card empty">Không tìm thấy điều kiện phù hợp.</div>'}`}`}
function criterionRow(u,c){const r=rec(u,c);return `<article class="criterion"><span class="criterion-code">${e(c.code)}</span><div class="criterion-main"><div class="criterion-title">${e(c.title)}</div><div class="criterion-meta"><span class="area-tag">${e(areaName(c.area))}</span>${badge(r?.status||'empty')}<span>Tối đa <strong>${c.maxScore}</strong> điểm</span>${r?.status==='approved'?`<span>Điểm duyệt: <strong>${r.score}</strong></span>`:''}${/Không yêu cầu đăng tải minh chứng/i.test(c.evidence)?'<span>Đánh giá trên hệ thống</span>':''}${r?.files?.length?`<span>${r.files.length} tệp đính kèm</span>`:''}</div></div><div class="criterion-actions">${store.explanations[u.id+'__'+c.id]?`<span class="badge ${store.explanations[u.id+'__'+c.id].status==='pending'?'submitted':'draft'}">${e(explanationLabel(store.explanations[u.id+'__'+c.id].status))}</span>`:''}<button class="btn small" data-criterion="${c.id}" data-owner="${u.id}">${admin()&&r?.status==='submitted'?'Chấm điểm':r?'Xem chi tiết':campaignClosed(store.settings)?'Xem / giải trình':'Thực hiện'}${icon('arrow',14)}</button></div></article>`}
function review(){const pending=activeRecords().filter(r=>(filter==='all'?r.status==='submitted':r.status===filter)&&matchesArea(criterionIndex.get(r.criterionId))&&(reviewGroup==='all'||units.find(u=>u.id===r.unitId)?.group===reviewGroup)&&`${units.find(u=>u.id===r.unitId)?.name} ${criterionIndex.get(r.criterionId)?.title}`.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi'))).sort((a,b)=>(a.updatedAt?.toMillis?.()||a.updatedAt||0)-(b.updatedAt?.toMillis?.()||b.updatedAt||0)),groups=[...new Set(pending.map(r=>r.unitId))];return `${head('Duyệt & chấm điểm','Hồ sơ được gom theo đơn vị; ưu tiên xử lý các hồ sơ gửi trước.',exportBtn())}<div class="filters"><div class="search">${icon('search',17)}<input id="search" value="${e(search)}" placeholder="Tìm đơn vị hoặc nội dung hồ sơ…"></div><select id="review-group" aria-label="Lọc khối"><option value="all">Tất cả khối thi đua</option>${options(sets,'name',reviewGroup)}</select>${areaSelect()}<select id="status-filter" aria-label="Lọc trạng thái duyệt"><option value="all">Chờ duyệt</option><option value="approved" ${filter==='approved'?'selected':''}>Đã chấm điểm</option><option value="returned" ${filter==='returned'?'selected':''}>Cần bổ sung</option></select></div><div class="result-summary"><strong>${pending.length}</strong> hồ sơ · <strong>${groups.length}</strong> đơn vị</div>${groups.map(id=>{const u=units.find(u=>u.id===id),rows=pending.filter(r=>r.unitId===id);return `<section class="card criteria-group"><div class="group-head"><div><h2>${e(u.name)}</h2><small>${e(setFor(u)?.name)} · ${rows.length} hồ sơ</small></div><button class="btn small" data-unit="${id}">Hồ sơ đơn vị ${icon('arrow',15)}</button></div>${rows.map(r=>{const c=setFor(u)?.items.find(c=>c.id===r.criterionId);return c?criterionRow(u,c):''}).join('')}</section>`}).join('')||'<div class="card empty">'+icon('check',40)+'<h2>Danh sách đã được xử lý</h2><p>Không có hồ sơ phù hợp với bộ lọc hiện tại.</p></div>'}`}
function ranking(){const rows=rankUnits(units,sets,store.records,selectedGroup).filter(u=>u.name.toLowerCase().includes(search.toLowerCase()));return `${head('Bảng xếp hạng','So sánh trong cùng một khối theo tổng điểm đã được Tỉnh Đoàn chấm.',exportBtn())}<div class="filters"><select id="group-select" aria-label="Khối thi đua">${options(sets,'name',selectedGroup)}</select><div class="search">${icon('search',16)}<input id="search" value="${e(search)}" placeholder="Tìm đơn vị…"></div></div>${discrepancy(sets.find(s=>s.id===selectedGroup))}<div class="notice info">${icon('help',16)}Xếp hạng tạm thời theo điểm duyệt, đồng điểm đồng hạng. Đơn vị chưa có điều kiện được chấm chưa xếp hạng. Đây chưa phải kết quả xếp loại chính thức.</div><div class="card">${unitTable(rows,true)}<div class="table-footer"><span>${rows.length} đơn vị trong khối</span><span>Chỉ tính điểm đã chấm</span></div></div>`}
function accounts(){return `${head('Quản lý tài khoản','114 tài khoản từ danh sách được cung cấp: 1 quản trị viên và 113 đơn vị.')}<div class="notice info">${icon('shield',17)}Mật khẩu được quản lý bằng Firebase Authentication; ứng dụng không hiển thị lại mật khẩu hiện tại.</div><div class="filters"><div class="search">${icon('search',16)}<input id="search" value="${e(search)}" placeholder="Tìm tài khoản, đơn vị…"></div><select id="account-group" aria-label="Lọc tài khoản theo khối"><option value="all">Tất cả khối thi đua</option>${options(sets,'name',accountGroup)}</select></div><div class="card"><div class="table-wrap"><table><thead><tr><th>ĐƠN VỊ</th><th>MÃ TÀI KHOẢN</th><th>BỘ TIÊU CHÍ</th><th>QUYỀN</th><th></th></tr></thead><tbody>${units.filter(u=>(accountGroup==='all'||u.group===accountGroup)&&`${u.id} ${u.name}`.toLowerCase().includes(search.toLowerCase())).map(u=>`<tr><td>${e(u.name)}</td><td>${u.id}</td><td>${u.role==='admin'?'Toàn tỉnh':e(setFor(u)?.name||'Chưa có bộ tiêu chí')}</td><td><span class="badge">${u.role==='admin'?'Quản trị viên':'Đơn vị'}</span></td><td><div class="buttonrow"><button class="btn small" data-reset="${u.id}">Đổi mật khẩu</button>${u.role!=='admin'?`<button class="btn small" data-unit-reset="${u.id}">Đặt lại số liệu</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div>`}
function chat(){if(chatOther===store.user.id)chatOther=units.find(u=>u.id!==store.user.id).id;return `${head('Trao đổi trực tiếp','Kết nối các đơn vị và Tỉnh Đoàn trong quá trình hoàn thiện hồ sơ.')}<div class="notice info">${icon('clock',16)}Tin nhắn hết hạn sau 7 ngày và được ẩn khỏi cuộc trò chuyện. Tác vụ máy chủ dọn dữ liệu hết hạn định kỳ; không dùng chat để lưu minh chứng.</div><section class="card chat-layout"><div class="chat-list"><div class="search">${icon('search',16)}<input id="contact-search" value="${e(chatSearch)}" placeholder="Tìm người trao đổi…" aria-label="Tìm người trao đổi"></div>${units.filter(u=>u.id!==store.user.id).map(u=>`<button class="chat-person ${chatOther===u.id?'active':''}" data-chat="${u.id}"><div class="avatar">${u.role==='admin'?'QT':'ĐV'}</div><span>${e(u.name)}<small class="status-line">${u.role==='admin'?'Quản trị Tỉnh Đoàn':e(setFor(u)?.name||'Đơn vị')}</small></span></button>`).join('')}</div><div class="chat-room"><div class="chat-head">${e(units.find(u=>u.id===chatOther)?.name)}</div><div id="messages" class="messages"></div><form class="chat-compose" id="chat-form"><input id="message-input" maxlength="2000" autocomplete="off" placeholder="Nhập tin nhắn…" aria-label="Nội dung tin nhắn" required><button class="btn primary" type="submit">Gửi ${icon('arrow',15)}</button></form></div></section>`}
function renderMessages(){const box=$('#messages');if(!box||!store.user)return;const atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<70;box.innerHTML=chatMessages.filter(m=>m.expiresAt>Date.now()).map(m=>`<div class="bubble ${m.from===store.user.id?'mine':''}">${e(m.text)}<small>${fmtDate(m.createdAt)}</small></div>`).join('')||'<div class="empty">'+icon('chat',30)+'<p>Chưa có tin nhắn trong 7 ngày gần đây.<br>Bắt đầu cuộc trao đổi với đơn vị.</p></div>';if(atBottom)box.scrollTop=box.scrollHeight;}
function loadChat(){store.watchChat(chatOther,m=>{chatMessages=m;renderMessages()},err)}
function settings(){return `${head('Thiết lập hệ thống','Quản lý thời hạn, dữ liệu và các thao tác của đợt thi đua.',`<button class="btn" data-action="backup">${icon('download',16)}Sao lưu dữ liệu JSON</button>`)}<div class="settings-grid"><section class="card"><div class="card-head"><div><h2>Đợt thi đua năm 2026</h2><small>Thời gian và quyền nộp hồ sơ</small></div><span class="pill ${store.settings.locked?'warn':''}">${store.settings.locked?'Đang khóa':'Đang mở'}</span></div><form id="campaign-form" class="card-body"><div class="field"><label for="deadline">Hạn nộp minh chứng (giờ Việt Nam)</label><input id="deadline" type="datetime-local" value="${e(store.settings.deadline||'')}"><small>Để trống khi chưa ban hành hạn nộp.</small></div><label class="checkbox-row"><input id="locked" type="checkbox" ${store.settings.locked?'checked':''}><span><strong>Khóa nộp minh chứng</strong><small>Tạm dừng lưu nháp, tải tệp và gửi hồ sơ. Đơn vị vẫn có thể gửi kiến nghị, giải trình.</small></span></label><button class="btn primary" ${store.settings.resetInProgress?'disabled':''}>Lưu thiết lập</button></form></section><section class="card"><div class="card-head"><div><h2>Trạng thái hệ thống</h2><small>Dữ liệu chung và phân quyền</small></div>${icon('shield',22)}</div><div class="card-body"><div class="system-row"><span>Đồng bộ hồ sơ</span><span class="badge approved">${store.demo?'Trải nghiệm':store.synced?'Đã đồng bộ':'Đang đồng bộ'}</span></div><div class="system-row"><span>Tài khoản được cấp</span><strong>114 tài khoản</strong></div><div class="system-row"><span>Tiêu chí chi tiết</span><strong>${sets.reduce((n,s)=>n+s.items.length,0)} điều kiện / 5 bộ</strong></div><div class="system-row"><span>Lưu trữ chat</span><strong>7 ngày</strong></div><div class="notice info compact">${icon('help',17)}Khối Đảng và UBND cần đối chiếu tổng điểm. Khối Quân sự chưa có bộ tiêu chí.</div></div></section><section class="card reset-card wide"><div class="card-head"><div><span class="eyebrow">QUẢN LÝ DỮ LIỆU</span><h2>Đặt lại số liệu thi đua</h2><small>Đưa hồ sơ, tiến độ và điểm của phạm vi được chọn về ban đầu.</small></div><span class="reset-icon">${icon('settings',24)}</span></div><div class="card-body"><div class="reset-layout"><div><p>Hồ sơ hiện tại được lưu thành bản sao trước khi đặt lại. Tài khoản, mật khẩu, bộ tiêu chí, tệp đính kèm và lịch sử hoạt động được giữ lại.</p><div class="reset-steps"><span>01 · Xem phạm vi</span><span>02 · Xác nhận quản trị</span><span>03 · Lưu bản sao và đặt lại</span></div></div><div><label for="reset-scope" class="field-label">Phạm vi đặt lại</label><select id="reset-scope"><option value="all">Toàn tỉnh · Tất cả đơn vị</option>${options(units.filter(u=>u.role!=='admin'),'name',selectedUnit)}</select><button class="btn danger" data-action="reset-preview" ${store.settings.resetInProgress?'disabled':''}>${icon('settings',16)}Xem trước số liệu cần đặt lại</button>${store.settings.resetInProgress?'<button class="btn primary" data-action="reset-resume">Tiếp tục thao tác đang dở</button>':''}</div></div></div></section><section class="card wide"><div class="card-head"><div><h2>Bản sao trước khi đặt lại</h2><small>10 lần đặt lại gần nhất · Chỉ quản trị viên được truy cập</small></div>${icon('clock',20)}</div><div class="table-wrap"><table><thead><tr><th>THỜI ĐIỂM</th><th>PHẠM VI</th><th>SỐ HỒ SƠ</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${(store.archives||[]).map(a=>`<tr><td>${fmtDate(a.createdAt)}</td><td>${e(a.scopeName)}</td><td>${num(a.count)}</td><td><span class="badge ${a.status==='complete'?'approved':'draft'}">${a.status==='complete'?'Đã lưu bản sao':'Đang lưu bản sao'}</span></td><td><button class="btn small" data-archive="${a.id}" ${a.status!=='complete'?'disabled':''}>${icon('download',15)}Tải bản sao JSON</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Chưa có lần đặt lại dữ liệu nào.</td></tr>'}</tbody></table></div></section></div>`}
function help(){return `${head('Hướng dẫn sử dụng','Hoàn thiện hồ sơ theo từng bước, theo dõi phản hồi ngay trên hệ thống.')}<div class="settings-grid"><div class="card"><div class="card-head"><h2>Dành cho các đơn vị</h2></div><div class="card-body">${[['01 · Chọn đúng đơn vị','Mở Minh chứng thi đua, kiểm tra bộ tiêu chí được gán cho tài khoản. Bạn có thể xem tiến độ đơn vị khác.'],['02 · Chuẩn bị minh chứng','Đọc nội dung, hướng dẫn đánh giá và yêu cầu minh chứng. Nhập kết quả, điểm tự chấm, đường dẫn hoặc tệp minh chứng.'],['03 · Lưu nháp và gửi duyệt','Lưu nháp để hoàn thiện sau. Khi gửi duyệt, hồ sơ được khóa chỉnh sửa. Quản trị viên có thể trả lại kèm phản hồi.'],['Đổi mật khẩu tài khoản','Chọn Đổi mật khẩu trong danh mục, nhập mật khẩu hiện tại và nhập mật khẩu mới hai lần. Mật khẩu mới từ 10 đến 128 ký tự. Nếu quên mật khẩu hiện tại, liên hệ quản trị viên Tỉnh Đoàn.'],['04 · Theo dõi kết quả','Kiểm tra điểm duyệt và yêu cầu bổ sung. Bảng xếp hạng so sánh trong cùng một bộ tiêu chí.']].map(([a,b])=>`<div class="help-step"><strong>${a}</strong>${b}</div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Dành cho quản trị viên</h2></div><div class="card-body"><div class="help-step"><strong>Duyệt và chấm điểm</strong>Mở danh sách chờ duyệt, kiểm tra từng tệp/đường dẫn. Điểm chấm không vượt mức tối đa. Khi trả lại hồ sơ, cần ghi rõ lý do.</div><div class="help-step"><strong>Xuất Excel</strong>Báo cáo gồm tổng hợp đơn vị và toàn bộ điều kiện chi tiết, điểm tự chấm, điểm duyệt, phản hồi và tên tệp. Tệp minh chứng không nhúng vào Excel.</div><div class="help-step"><strong>Dữ liệu được chia sẻ</strong>Tài khoản đã được cấp quyền có thể xem minh chứng và tiến độ các đơn vị. Chat riêng chỉ hai bên tham gia được đọc. Không gửi mật khẩu qua chat.</div><div class="help-step"><strong>Bảo vệ dữ liệu</strong>Chỉ quản trị viên được đặt lại số liệu. Thao tác cần xác nhận đúng phạm vi, nhập mật khẩu và cụm xác nhận; hồ sơ được lưu bản sao trước khi đặt lại.</div></div></div></div>`}
function fmtDate(v){const d=v?.toDate?v.toDate():new Date(v);return isNaN(+d)?'':d.toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
function audit(){return `${head('Nhật ký hoạt động','Theo dõi các lần gửi, chấm điểm và thay đổi thiết lập gần đây.')}<div class="card"><div class="table-wrap"><table><thead><tr><th>THỜI GIAN</th><th>NGƯỜI THỰC HIỆN</th><th>THAO TÁC</th><th>ĐƠN VỊ / ĐIỀU KIỆN</th></tr></thead><tbody>${store.audits.map(a=>`<tr><td>${fmtDate(a.at)}</td><td>${e(a.actor)}</td><td>${e(a.action)}</td><td>${e(a.unit)} ${e(a.code)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Chưa có hoạt động được ghi nhận.</td></tr>'}</tbody></table></div></div>`}
function modal(title,body,foot=''){const previous=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-close aria-label="Đóng">${icon('close')}</button></header><div class="modal-content">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`;modal.previous=previous;all('[data-close]').forEach(b=>b.onclick=closeModal);$('#modal-root').onkeydown=ev=>{if(ev.key==='Escape')closeModal();if(ev.key==='Tab'){const els=all('#modal-root button:not(:disabled), #modal-root input:not(:disabled), #modal-root textarea:not(:disabled), #modal-root a, #modal-root select');const f=els[0],l=els.at(-1);if(ev.shiftKey&&document.activeElement===f){ev.preventDefault();l.focus()}else if(!ev.shiftKey&&document.activeElement===l){ev.preventDefault();f.focus()}}};$('#modal-root [data-close]').focus()}
function closeModal(){if(modal.busy)return;store.stopExplanation();$('#modal-root').innerHTML='';editState=null;modal.previous?.focus()}
function openCriterion(uid,cid){const u=units.find(u=>u.id===uid),c=criterionIndex.get(cid),r=rec(u,c),editable=c.active!==false&&(admin()||u.id===store.user.id)&&!['approved','submitted'].includes(r?.status)&&!campaignClosed(store.settings)&&!store.settings.resetInProgress;editState={u,c,r,files:[...(r?.files||[])]};modal(`Điều kiện ${e(c.code)} · ${e(u.name)}`,`<p style="line-height:1.9;font-weight:500">${e(c.title)}</p><div class="criterion-meta">${badge(r?.status||'empty')}<strong>Tối đa ${c.maxScore} điểm</strong></div><div class="field"><label>Hướng dẫn đánh giá</label><div class="requirement">${e(c.evaluation)}</div></div><div class="field"><label>Yêu cầu minh chứng</label><div class="requirement">${e(c.evidence)}</div></div>${r?.feedback?`<div class="notice"><strong>Phản hồi:</strong> ${e(r.feedback)}</div>`:''}<div class="field"><label for="e-note">Kết quả thực hiện</label><textarea id="e-note" maxlength="10000" placeholder="Mô tả hoạt động, thời gian, đối tượng và kết quả đạt được…" ${editable?'':'disabled'}>${e(r?.note||'')}</textarea></div><div class="split"><div class="field"><label for="e-self">Điểm tự chấm</label><input id="e-self" type="number" min="0" max="${c.maxScore}" step="0.5" value="${r?.selfScore??0}" ${editable?'':'disabled'}></div><div class="field"><label>Điểm được duyệt</label><input disabled value="${r?.score??'Chưa chấm'}"></div></div><div class="field"><label for="e-links">Đường dẫn minh chứng</label><textarea id="e-links" style="min-height:80px" placeholder="Mỗi dòng một đường dẫn https://…" ${editable?'':'disabled'}>${e(r?.links?.join('\n')||'')}</textarea>${(r?.links||[]).map(l=>safeLink(l)?`<div class="attachment">${icon('link',14)}<a href="${e(safeLink(l))}" target="_blank" rel="noopener noreferrer">${e(l)}</a></div>`:'').join('')}</div><div class="field"><label>Tệp minh chứng</label><div id="e-files"></div>${editable?'<div class="upload"><input type="file" id="e-upload" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.xlsx"><small>Ảnh JPG, PNG, WEBP: tối đa 5 MB/ảnh · PDF, Word, Excel: tối đa 10 MB/tệp · 10 tệp/điều kiện</small></div>':''}</div>${explanationSection(u,c)}${admin()&&c.active!==false&&r&&['submitted','approved'].includes(r.status)?`<div class="requirement"><h3>Đánh giá của Tỉnh Đoàn</h3><div class="field"><label for="e-score">Điểm chấm (0–${c.maxScore})</label><input id="e-score" type="number" step="0.5" min="0" max="${c.maxScore}" value="${r.score??r.selfScore}"></div><div class="field"><label for="e-feedback">Nhận xét / yêu cầu bổ sung</label><textarea id="e-feedback" maxlength="4000" placeholder="Ghi rõ nội dung cần bổ sung…">${e(r.feedback||'')}</textarea></div></div>`:''}`,`<button class="btn" data-close>Đóng</button>${editable?'<button class="btn" id="save-draft">Lưu nháp</button><button class="btn primary" id="submit-evidence">Gửi duyệt</button>':''}${admin()&&c.active!==false&&r&&['submitted','approved'].includes(r.status)?`<button class="btn danger" id="return-evidence">Yêu cầu bổ sung</button>${r.status==='submitted'?'<button class="btn primary" id="approve-evidence">Duyệt & ghi điểm</button>':''}`:''}`);fileList();bindExplanation(u,c);$('#e-upload')?.addEventListener('change',async ev=>{const input=ev.target;modal.busy=true;input.disabled=true;all('.modal button').forEach(b=>b.disabled=true);try{for(const f of input.files){if(editState.files.length>=10)throw Error('Tối đa 10 tệp cho mỗi điều kiện.');toast('Đang tải tệp…');editState.files.push(await store.upload(u,c,f));}fileList();toast('Đã tải tệp. Hãy lưu nháp hoặc gửi duyệt.')}catch(x){err(x)}finally{modal.busy=false;input.value='';input.disabled=false;all('.modal button').forEach(b=>b.disabled=false)}});$('#save-draft')?.addEventListener('click',()=>saveEvidence('draft'));$('#submit-evidence')?.addEventListener('click',()=>saveEvidence('submitted'));$('#approve-evidence')?.addEventListener('click',()=>reviewEvidence('approved'));$('#return-evidence')?.addEventListener('click',()=>reviewEvidence('returned'));}
function fileList(){const box=$('#e-files');if(!box||!editState)return;box.innerHTML=editState.files.map((f,i)=>`<div class="attachment">${icon('file',15)}<button class="linkbutton" data-preview="${i}" title="Xem trước nội dung" aria-label="Xem trước ${e(f.name)}">${e(f.name)}</button><small>${Math.round(f.size/1024)} KB</small><button class="btn small" data-download="${i}" aria-label="Tải về ${e(f.name)}" title="Tải bản gốc về máy">${icon('download',15)}Tải về</button>${$('#e-upload')?`<button data-remove="${i}" aria-label="Bỏ tệp ${e(f.name)}">${icon('close',14)}</button>`:''}</div>`).join('')||'<div class="muted" style="padding:10px 0;font-size:11px">Chưa có tệp đính kèm.</div>';all('[data-remove]').forEach(b=>b.onclick=()=>{editState.files.splice(+b.dataset.remove,1);fileList()});all('[data-preview]').forEach(b=>b.onclick=()=>{const f=editState?.files[+b.dataset.preview];if(f)openEvidencePreview(f,{load:file=>store.download(file),download:downloadBlob})});all('[data-download]').forEach(b=>b.onclick=async()=>{const index=b.dataset.download,f=editState?.files[+index];if(!f)return;const buttons=all('[data-download]').filter(x=>x.dataset.download===index);buttons.forEach(x=>x.disabled=true);try{toast('Đang tải tệp minh chứng…');const blob=await store.download(f);downloadBlob(blob,f.name);toast('Đã tải tệp về máy. Mở tệp trong thư mục tải xuống để xem.')}catch(x){err(x)}finally{buttons.forEach(x=>x.disabled=false)}})}
async function saveEvidence(status){const {u,c,r,files}=editState;const data={note:$('#e-note').value.trim(),selfScore:Number($('#e-self').value),links:$('#e-links').value.split('\n').map(s=>s.trim()).filter(Boolean),files,revision:r?.revision||0};try{validateSubmission(c,data,status);await busyModal(()=>store.save(u,c,data,status));closeModal();render();toast(status==='submitted'?'Đã gửi minh chứng để duyệt.':'Đã lưu bản nháp.')}catch(x){err(x)}}
async function reviewEvidence(status){const {u,c,r}=editState;const score=Number($('#e-score').value),feedback=$('#e-feedback').value.trim();try{if(status==='approved'&&(!Number.isFinite(score)||score<0||score>c.maxScore))throw Error('Điểm chấm phải từ 0 đến '+c.maxScore);if(status==='returned'&&!feedback)throw Error('Vui lòng nhập lý do yêu cầu bổ sung.');await busyModal(()=>store.review(u,c,score,feedback,status,r.revision));closeModal();render();toast(status==='approved'?'Đã duyệt và ghi nhận điểm.':'Đã gửi yêu cầu bổ sung.')}catch(x){err(x)}}
async function busyModal(fn){modal.busy=true;const bs=all('.modal button');bs.forEach(b=>b.disabled=true);try{return await fn()}finally{modal.busy=false;bs.forEach(b=>b.disabled=false)}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function exportExcel(){if(exportExcel.busy)return;exportExcel.busy=true;try{toast('Đang tạo báo cáo Excel…');const ExcelJS=(await import('exceljs')).default;const wb=new ExcelJS.Workbook();wb.creator='Tỉnh Đoàn Đồng Tháp';const summary=wb.addWorksheet('Tổng hợp'),details=wb.addWorksheet('Chi tiết minh chứng');summary.columns=[{header:'Đơn vị',key:'name',width:38},{header:'Khối',key:'group',width:26},{header:'Tổng điều kiện',key:'total',width:17},{header:'Đã gửi / duyệt',key:'done',width:18},{header:'Đã chấm',key:'approved',width:13},{header:'Tiến độ gửi',key:'progress',width:15},{header:'Điểm duyệt',key:'score',width:15},{header:'Điểm tối đa chi tiết',key:'max',width:22},{header:'Lưu ý',key:'note',width:60}];details.columns=[{header:'Đơn vị',width:35},{header:'Khối',width:24},{header:'Mã',width:10},{header:'Nội dung điều kiện',width:85},{header:'Tối đa',width:10},{header:'Tự chấm',width:12},{header:'Điểm duyệt',width:13},{header:'Trạng thái',width:20},{header:'Kết quả thực hiện',width:65},{header:'Đường dẫn',width:55},{header:'Tệp minh chứng',width:50},{header:'Phản hồi',width:50},{header:'Lĩnh vực phụ trách',width:32}];for(const u of units.filter(u=>u.role!=='admin')){const m=metrics(u,sets,store.records),s=setFor(u);summary.addRow({...m,name:u.name,group:s?.name||'Chưa gán',progress:m.total?m.done/m.total:0,score:m.approved?m.score:null,note:!s?'Chưa được cung cấp bộ tiêu chí':['g4','g5'].includes(s.id)?'Tổng đầu văn bản không khớp chi tiết; cần đối chiếu.':''});for(const c of s?.items||[]){const r=rec(u,c);details.addRow([u.name,s.name,c.code,c.title,c.maxScore,r?.selfScore??null,r?.status==='approved'?r.score:null,statuses[r?.status||'empty'],r?.note||'',(r?.links||[]).join('\n'),(r?.files||[]).map(f=>f.name).join('\n'),r?.feedback||'',areaName(c.area)])}}summary.getColumn('progress').numFmt='0%';for(const sheet of [summary,details]){sheet.views=[{state:'frozen',ySplit:1}];sheet.autoFilter={from:'A1',to:{row:sheet.rowCount,column:sheet.columnCount}};sheet.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};sheet.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF0066CC'}};sheet.getRow(1).height=30;sheet.eachRow((row,n)=>{row.alignment={vertical:'top',wrapText:true};if(n>1){row.font={name:'Calibri',size:11};row.height=sheet===details?65:36;if(n%2===0)row.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF2F7FC'}}}})}const explanationsSheet=wb.addWorksheet('Kiến nghị giải trình');explanationsSheet.columns=[{header:'Đơn vị',width:35},{header:'Mã điều kiện',width:16},{header:'Nội dung điều kiện',width:65},{header:'Lĩnh vực',width:32},{header:'Trạng thái',width:24},{header:'Dự kiến hoàn thành',width:24},{header:'Cập nhật',width:25},{header:'Lý do của đơn vị',width:80},{header:'Phản hồi gần nhất',width:80}];for(const r of Object.values(store.explanations))explanationsSheet.addRow([units.find(u=>u.id===r.unitId)?.name,r.criterionCode,r.criterionTitle,areaName(criterionIndex.get(r.criterionId)?.area),explanationLabel(r.status),r.expectedDate||'',fmtDate(r.updatedAt),r.reason||r.lastText,r.lastReply||'']);explanationsSheet.getRow(1).font={bold:true};explanationsSheet.eachRow(row=>row.alignment={wrapText:true,vertical:'top'});const note=wb.addWorksheet('Thông tin');note.getColumn(1).width=110;note.addRows([['Hệ thống minh chứng thi đua tỉnh Đoàn Đồng Tháp năm 2026'],['Thời điểm xuất: '+new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})],[store.demo?'DỮ LIỆU TRẢI NGHIỆM — không phải kết quả thi đua chính thức':'Dữ liệu hiện tại từ hệ thống; điểm chưa chấm để trống.'],['Nguồn: 5 văn bản tiêu chí Phần 1 và danh sách đơn vị do người dùng cung cấp.'],['Khối Đảng: tổng ghi 26 điều kiện/113 điểm; chi tiết 27/123. Khối UBND: tổng ghi 25/117; chi tiết 28/130.'],['Chưa có bộ tiêu chí của Đoàn Thanh niên Quân sự Tỉnh. Xếp hạng tạm thời chỉ so sánh cùng khối.']]);note.eachRow(r=>{r.alignment={wrapText:true};r.height=32});const buf=await wb.xlsx.writeBuffer();downloadBlob(new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`Bao-cao-thi-dua-2026${store.demo?'-TRAI-NGHIEM':''}.xlsx`);toast('Đã xuất báo cáo Excel.')}catch(x){err(x)}finally{exportExcel.busy=false}}
function bind(){bindManagement();all('[data-page]').forEach(b=>b.onclick=()=>{const previousPage=page;page=b.dataset.page;if(previousPage==='dashboard'&&admin()){if(page==='review')reviewGroup=dashboardGroup;if(page==='criteria'&&dashboardGroup!=='all')selectedUnit=units.find(u=>u.role!=='admin'&&u.group===dashboardGroup)?.id||selectedUnit;}drawer=false;search='';filter='all';areaFilter='all';store.stopChat();chatMessages=[];render();if(page==='chat')loadChat()});all('[data-action]').forEach(b=>b.onclick=async()=>{switch(b.dataset.action){case'change-password':openChangePassword();break;case'quick-search':quickSearch();break;case'notifications':notifications();break;case'backup':downloadBlob(new Blob([JSON.stringify({year:2026,exportedAt:new Date().toISOString(),settings:store.settings,records:store.records},null,2)],{type:'application/json'}),'Sao-luu-thi-dua-2026.json');break;case'reset-preview':await startReset();break;case'reset-resume':await startReset(true);break;case'close-menu':drawer=false;render();break;case'export':await exportExcel();break;case'logout':await store.logout();page='dashboard';login();break;case'menu':drawer=!drawer;render();break}});all('[data-unit]').forEach(b=>b.onclick=()=>{selectedUnit=b.dataset.unit;page='criteria';search='';filter='all';render()});all('[data-overview]').forEach(b=>b.onclick=()=>{dashboardGroup=b.dataset.overview;render()});all('[data-archive]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;const records=await store.downloadArchive(b.dataset.archive);downloadBlob(new Blob([JSON.stringify({archiveId:b.dataset.archive,records},null,2)],{type:'application/json'}),'Ban-sao-thi-dua-'+b.dataset.archive+'.json')}catch(x){err(x)}finally{b.disabled=false}});$('#contact-search')?.addEventListener('input',ev=>{chatSearch=ev.target.value;filterContacts()});$('#account-group')?.addEventListener('change',ev=>{accountGroup=ev.target.value;render()});all('[data-unit-reset]').forEach(b=>b.onclick=()=>startReset(false,b.dataset.unitReset));all('[data-status-chip]').forEach(b=>b.onclick=()=>{filter=b.dataset.statusChip;render()});$('#review-group')?.addEventListener('change',ev=>{reviewGroup=ev.target.value;render()});$('#unit-select')?.addEventListener('change',ev=>{selectedUnit=ev.target.value;render()});$('#group-select')?.addEventListener('change',ev=>{selectedGroup=ev.target.value;render()});$('#status-filter')?.addEventListener('change',ev=>{filter=ev.target.value;render()});$('#search')?.addEventListener('input',ev=>{const pos=ev.target.selectionStart;search=ev.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});all('[data-criterion]').forEach(b=>b.onclick=()=>openCriterion(b.dataset.owner,b.dataset.criterion));all('[data-source]').forEach(b=>b.onclick=()=>modal('Văn bản nguồn',`<pre class="source-pre">${e(sets.find(s=>s.id===b.dataset.source).sourceText)}</pre>`));all('[data-chat]').forEach(b=>b.onclick=()=>{chatOther=b.dataset.chat;render();loadChat()});$('#chat-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const input=$('#message-input'),text=input.value.trim();if(!text)return;ev.submitter.disabled=true;try{await store.send(chatOther,text);$('#message-input').value=''}catch(x){err(x)}finally{if(ev.submitter)ev.submitter.disabled=false}});$('#campaign-form')?.addEventListener('submit',async ev=>{ev.preventDefault();try{await store.updateSettings({deadline:$('#deadline').value,locked:$('#locked').checked});toast('Đã lưu thiết lập.')}catch(x){err(x)}});all('[data-reset]').forEach(b=>b.onclick=()=>{const u=units.find(u=>u.id===b.dataset.reset);modal('Đổi mật khẩu',`<p>${e(u.name)}</p>${store.demo?'<div class="notice" style="margin-top:16px">Cần kết nối Firebase để đổi mật khẩu tài khoản thật.</div>':''}<div class="field"><label for="new-password">Mật khẩu mới (ít nhất 10 ký tự)</label><input type="password" id="new-password" minlength="10" autocomplete="new-password"></div>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" id="confirm-reset" ${store.demo?'disabled':''}>Đổi mật khẩu</button>`);$('#confirm-reset').onclick=async()=>{try{const p=$('#new-password').value;if(p.length<10)throw Error('Mật khẩu cần ít nhất 10 ký tự.');await busyModal(()=>store.resetPassword(u.id,p));closeModal();toast('Đã đổi mật khẩu.')}catch(x){err(x)}}});}
if(store.demo){store.user={...units.find(u=>u.id==='admin')};render();window.addEventListener('storage',ev=>{if(ev.key==='dt2026-demo'){store.loadDemo();render();if(page==='chat')loadChat()}})}else{login();await store.observe(u=>{if(u){selectedUnit=u.role==='admin'?units.find(x=>x.role!=='admin').id:u.id;render()}else login()},err)}
setInterval(()=>{if(page==='chat')renderMessages()},30000);

function quickSearch(){if(modal.busy)return;modal('Tìm nhanh',`<div class="search"><input id="quick-input" placeholder="Tên đơn vị, mã hoặc nội dung điều kiện…" autocomplete="off" aria-label="Tìm nhanh"></div><div id="quick-results" class="quick-results"></div>`);const update=()=>{const q=$('#quick-input').value.toLocaleLowerCase('vi').trim(),u=unit(),s=setFor(u),us=units.filter(x=>x.role!=='admin'&&x.name.toLocaleLowerCase('vi').includes(q)).slice(0,6),cs=(s?.items||[]).filter(c=>q&&`${c.code} ${c.title} ${areaName(c.area)}`.toLocaleLowerCase('vi').includes(q)).slice(0,5);$('#quick-results').innerHTML=us.map(x=>`<button data-quick-unit="${x.id}">${icon('building',19)}<span><strong>${e(x.name)}</strong><small>${e(setFor(x)?.name||'Chưa gán bộ tiêu chí')}</small></span>${icon('arrow',16)}</button>`).join('')+cs.map(c=>`<button data-quick-criterion="${c.id}">${icon('file',19)}<span><strong>${e(c.code)} · ${e(c.title)}</strong><small>Hồ sơ của ${e(u.name)}</small></span></button>`).join('');all('[data-quick-unit]').forEach(b=>b.onclick=()=>{selectedUnit=b.dataset.quickUnit;page='criteria';search='';filter='all';store.stopChat();closeModal();render()});all('[data-quick-criterion]').forEach(b=>b.onclick=()=>{const id=b.dataset.quickCriterion;closeModal();openCriterion(u.id,id)});};$('#quick-input').oninput=update;update();$('#quick-input').focus();}
function notifications(){const rows=activeRecords().filter(r=>r.status===(admin()?'submitted':'returned')&&(admin()||r.unitId===store.user.id));modal('Công việc cần xử lý',`<div class="quick-results">${rows.slice(0,30).map(r=>{const u=units.find(u=>u.id===r.unitId),c=setFor(u)?.items.find(c=>c.id===r.criterionId);return `<button data-work-unit="${r.unitId}" data-work-code="${r.criterionId}">${icon('file',19)}<span><strong>${e(u?.name)} · ${e(c?.code)}</strong><small>${e(c?.title)}</small></span>${badge(r.status)}</button>`}).join('')||'<div class="empty">Không có công việc đang chờ xử lý.</div>'}</div>`);all('[data-work-code]').forEach(b=>b.onclick=()=>{const id=b.dataset.workCode,u=b.dataset.workUnit;closeModal();openCriterion(u,id)});}
async function startReset(resume=false,scopeOverride){if(!admin())return;try{let preview;if(resume){const scope=store.settings.resetScope;preview={requestId:store.settings.resetJob,scope,scopeName:scope==='all'?'Toàn tỉnh':units.find(u=>u.id===scope)?.name,counts:{total:Object.values(store.records).filter(r=>scope==='all'||r.unitId===scope).length}};}else{toast('Đang kiểm tra số hồ sơ…');preview=await store.prepareReset(scopeOverride||$('#reset-scope').value)}const empty=preview.counts.total===0&&!resume;modal(resume?'Tiếp tục đặt lại số liệu':'Xác nhận đặt lại số liệu',`<div class="reset-preview"><span>Phạm vi đã chọn</span><h3>${e(preview.scopeName)}</h3><strong>${num(preview.counts.total)} <small>hồ sơ ${resume?'còn lại':'bị ảnh hưởng'}</small></strong></div>${empty?'<div class="notice info">Phạm vi này chưa có hồ sơ. Không cần đặt lại số liệu.</div>':`<div class="notice">${icon('help',18)}${resume?'Tiếp tục lưu bản sao và xử lý những hồ sơ còn lại của thao tác đang dở.':'Sau thao tác, hồ sơ và điểm của phạm vi này được đưa về ban đầu. Bản sao được lưu trên máy chủ; có thể tải tại Thiết lập hệ thống.'}</div><button class="btn small" id="before-reset-export">${icon('download',15)}Xuất Excel trước khi đặt lại</button>${store.demo?'':`<div class="field"><label for="reset-password">Xác nhận mật khẩu quản trị viên</label><input id="reset-password" type="password" autocomplete="current-password" placeholder="Mật khẩu tài khoản đang đăng nhập"></div>`}<div class="field"><label for="reset-phrase">Nhập DAT LAI 2026 để xác nhận</label><input id="reset-phrase" autocomplete="off" placeholder="DAT LAI 2026"></div><label class="checkbox-row"><input id="reset-ack" type="checkbox"><span>Tôi đã kiểm tra đúng phạm vi và hiểu số liệu hiện tại sẽ được đặt lại.</span></label>`}`,`<button class="btn" data-close>Hủy thao tác</button>${empty?'':'<button class="btn danger filled" id="commit-reset" disabled>Xác nhận đặt lại</button>'}`);if(empty)return;$('#before-reset-export').onclick=exportExcel;const validate=()=>$('#commit-reset').disabled=!($('#reset-phrase').value==='DAT LAI 2026'&&$('#reset-ack').checked&&(store.demo||$('#reset-password').value));all('#reset-phrase,#reset-password,#reset-ack').forEach(x=>x.oninput=validate);$('#commit-reset').onclick=async()=>{const phrase=$('#reset-phrase').value,password=$('#reset-password')?.value;try{await busyModal(async()=>{await store.confirmIdentity(password);toast('Đang lưu bản sao và đặt lại số liệu…');await store.commitReset(preview,phrase)});closeModal();render();toast('Đã đặt lại số liệu và lưu bản sao hồ sơ.')}catch(x){err(x);validate()}};}catch(x){err(x)}}
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'&&store.user&&!modal.busy){ev.preventDefault();quickSearch()}});
window.addEventListener('offline',()=>{store.synced=false;if(store.user)render(true);toast('Mất kết nối mạng. Hãy kết nối lại trước khi gửi hồ sơ.')});
window.addEventListener('online',()=>{if(store.user)toast('Đã có mạng. Đang đồng bộ dữ liệu…')});

function filterContacts(){all('.chat-person').forEach(b=>b.hidden=!b.textContent.toLocaleLowerCase('vi').includes(chatSearch.toLocaleLowerCase('vi')));}

function openChangePassword(){
  if(!store.user||admin())return;
  modal('Đổi mật khẩu tài khoản',`<p class="subtitle">${e(store.user.name)}</p><p>Chỉ áp dụng cho tài khoản đang đăng nhập. Hồ sơ minh chứng của đơn vị được giữ nguyên.</p>${store.demo?'<div class="notice info">Bản trải nghiệm không đổi mật khẩu thật. Hãy đăng nhập tài khoản được cấp để sử dụng.</div>':''}<form id="own-password-form"><div class="field"><label for="own-current-password">Mật khẩu hiện tại</label><input id="own-current-password" type="password" autocomplete="current-password" required></div><div class="field"><label for="own-new-password">Mật khẩu mới</label><input id="own-new-password" type="password" autocomplete="new-password" minlength="10" maxlength="128" aria-describedby="own-password-hint" required><small id="own-password-hint">Từ 10 đến 128 ký tự, khác mật khẩu hiện tại.</small></div><div class="field"><label for="own-confirm-password">Xác nhận mật khẩu mới</label><input id="own-confirm-password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></div><label class="checkbox-row"><input type="checkbox" id="own-show-password"><span>Hiện mật khẩu</span></label><div id="own-password-error" class="notice" role="alert" hidden></div><div class="own-password-actions"><button class="btn" type="button" data-close>Hủy</button><button class="btn primary" type="submit" ${store.demo?'disabled':''}>Lưu mật khẩu mới</button></div></form>`);
  $('#own-show-password').onchange=ev=>all('#own-password-form input[autocomplete]').forEach(input=>input.type=ev.target.checked?'text':'password');
  $('#own-password-form').onsubmit=async ev=>{
    ev.preventDefault();if(modal.busy)return;
    const current=$('#own-current-password'),next=$('#own-new-password'),confirm=$('#own-confirm-password'),message=$('#own-password-error'),button=ev.submitter;
    message.hidden=true;
    try{
      validatePasswordChange(current.value,next.value,confirm.value);
      const values=[current.value,next.value,confirm.value];
      await busyModal(async()=>{
        all('#own-password-form input').forEach(input=>input.disabled=true);
        button.textContent='Đang đổi mật khẩu…';
        await store.changePassword(...values);
      });
      current.value=next.value=confirm.value='';closeModal();toast('Đã đổi mật khẩu thành công. Từ lần đăng nhập sau, hãy dùng mật khẩu mới.');
    }catch(error){
      all('#own-password-form input').forEach(input=>input.disabled=false);
      current.value='';message.textContent=passwordErrorMessage(error);message.hidden=false;
      button.textContent='Lưu mật khẩu mới';current.focus();
    }
  };
  $('#own-current-password').focus();
}

function activeRecords(){return Object.values(store.records).filter(r=>criterionIndex.get(r.criterionId)?.active!==false)}
function syncCatalog(){const catalog=makeCatalog(baseSets,store.criteria);sets=catalog.sets;criterionIndex.clear();for(const [id,c] of catalog.all)criterionIndex.set(id,c)}
function sectionLabel(title){return String(title).replace(/\s*\([^)]*(?:điều kiện|nội dung đánh giá)[^)]*\)\s*$/i,'')}
function areaName(id){return AREAS.find(a=>a.id===id)?.name||'Chưa phân loại'}
function matchesArea(c){return c&&(areaFilter==='all'||c.area===areaFilter)}
function areaSelect(){return `<select id="area-filter" aria-label="Lọc lĩnh vực"><option value="all">Tất cả lĩnh vực</option>${AREAS.map(a=>`<option value="${a.id}" ${areaFilter===a.id?'selected':''}>${e(a.name)}</option>`).join('')}</select>`}
function explanationLabel(status){return {pending:'Chờ phản hồi',answered:'Đã phản hồi',resolved:'Đã kết thúc'}[status]||'Chưa giải trình'}
function manageCriteria(){
 const rows=[...criterionIndex.values()].filter(c=>c.group===manageGroup&&matchesArea(c)&&(manageActive==='all'||(manageActive==='active'?c.active!==false:c.active===false))&&`${c.code} ${c.title} ${c.section} ${areaName(c.area)}`.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));
 return `${head('Quản lý bộ tiêu chí','Thêm, chỉnh sửa và phân loại điều kiện; thay đổi được đồng bộ cho các đơn vị.',`<button class="btn primary" id="add-criterion">${icon('file',16)}Thêm điều kiện</button>`)}<div class="filters"><select id="manage-group" aria-label="Bộ tiêu chí">${options(sets,'name',manageGroup)}</select>${areaSelect()}<select id="manage-active" aria-label="Trạng thái áp dụng"><option value="active" ${manageActive==='active'?'selected':''}>Đang áp dụng</option><option value="archived" ${manageActive==='archived'?'selected':''}>Ngừng áp dụng</option><option value="all" ${manageActive==='all'?'selected':''}>Tất cả điều kiện</option></select><div class="search">${icon('search',16)}<input id="search" placeholder="Mã, nội dung hoặc lĩnh vực…" value="${e(search)}"></div></div><div class="notice info">Ngừng áp dụng sẽ loại điều kiện khỏi danh sách thực hiện và tổng điểm hiện hành. Hồ sơ, tệp và lịch sử được giữ lại; admin có thể khôi phục.</div><div class="result-summary"><strong>${rows.length}</strong> điều kiện phù hợp</div><div class="card">${rows.map(c=>`<article class="criterion"><span class="criterion-code">${e(c.code)}</span><div class="criterion-main"><div class="criterion-title">${e(c.title)}</div><div class="criterion-meta"><span class="area-tag">${e(areaName(c.area))}</span><span>${c.maxScore} điểm</span><span class="badge ${c.active===false?'returned':'approved'}">${c.active===false?'Ngừng áp dụng':'Đang áp dụng'}</span><span>Phiên bản ${c.revision||0}</span></div><p class="status-line">${e(c.section)}</p></div><div class="criterion-actions"><button class="btn small" data-edit-criterion="${c.id}">Chỉnh sửa</button><button class="btn small" data-criterion-history="${c.id}">Lịch sử</button><button class="btn small ${c.active===false?'':'danger'}" data-toggle-criterion="${c.id}">${c.active===false?'Khôi phục':'Ngừng áp dụng'}</button></div></article>`).join('')||'<div class="empty">Không có điều kiện phù hợp.</div>'}</div>`;
}
function criterionForm(id){
 if(!admin())return;
 const c=id?criterionIndex.get(id):{group:manageGroup,code:'',title:'',section:sets.find(s=>s.id===manageGroup).groups[0]?.title||'Điều kiện bổ sung',maxScore:0,evaluation:'',evidence:'',area:'organization',active:true,revision:0};
 modal(id?'Chỉnh sửa điều kiện':'Thêm điều kiện',`<form id="criterion-form"><div class="notice info">Nội dung mới áp dụng cho các đơn vị trong bộ tiêu chí. Hồ sơ đã có được giữ nguyên; mỗi lần chỉnh sửa đều lưu lịch sử.</div><div class="split"><div class="field"><label for="c-group">Bộ tiêu chí</label><select id="c-group" ${id?'disabled':''}>${options(sets,'name',c.group)}</select></div><div class="field"><label for="c-code">Mã điều kiện</label><input id="c-code" maxlength="30" value="${e(c.code)}" placeholder="Ví dụ: 7.1" required></div></div><div class="field"><label for="c-title">Nội dung điều kiện</label><textarea id="c-title" maxlength="4000" required>${e(c.title)}</textarea></div><div class="split"><div class="field"><label for="c-area">Lĩnh vực phụ trách</label><select id="c-area">${AREAS.map(a=>`<option value="${a.id}" ${c.area===a.id?'selected':''}>${e(a.name)}</option>`).join('')}</select></div><div class="field"><label for="c-max">Điểm tối đa</label><input id="c-max" type="number" min="0" max="10000" step="0.5" value="${c.maxScore}" required></div></div><div class="field"><label for="c-section">Nhóm nội dung trong bộ tiêu chí</label><input id="c-section" list="c-sections" maxlength="500" value="${e(c.section)}" required><datalist id="c-sections">${sets.flatMap(s=>s.groups).map(g=>`<option value="${e(g.title)}">`).join('')}</datalist></div><div class="field"><label for="c-evaluation">Hướng dẫn đánh giá</label><textarea id="c-evaluation" maxlength="10000" required>${e(c.evaluation)}</textarea></div><div class="field"><label for="c-evidence">Yêu cầu minh chứng</label><textarea id="c-evidence" maxlength="10000" required>${e(c.evidence)}</textarea><small>Nếu miễn tải minh chứng, ghi rõ “Không yêu cầu đăng tải minh chứng”.</small></div></form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" id="save-criterion" form="criterion-form">Lưu điều kiện</button>`);
 $('#criterion-form').onsubmit=async ev=>{ev.preventDefault();const data={...(id?{id}:{}),group:$('#c-group').value,code:$('#c-code').value,title:$('#c-title').value,section:$('#c-section').value,area:$('#c-area').value,maxScore:Number($('#c-max').value),evaluation:$('#c-evaluation').value,evidence:$('#c-evidence').value,active:c.active!==false,revision:c.revision||0};try{await busyModal(()=>store.updateCriterion(data,criterionIndex));closeModal();render();toast('Đã lưu điều kiện và lịch sử thay đổi.')}catch(error){err(error)}};
}
function toggleCriterion(id){
 if(!admin())return;const c=criterionIndex.get(id),active=c.active===false,count=Object.values(store.records).filter(r=>r.criterionId===id).length;
 modal(active?'Khôi phục điều kiện':'Ngừng áp dụng điều kiện',`<p><strong>${e(c.code)} · ${e(c.title)}</strong></p><div class="notice ${active?'info':''}">${active?'Điều kiện sẽ xuất hiện trở lại trong bộ tiêu chí và được tính trong tổng điểm hiện hành.':`Điều kiện sẽ ngừng áp dụng với các đơn vị trong khối. ${count} hồ sơ đã có cùng các tệp đính kèm vẫn được giữ lại. Có thể khôi phục bất cứ lúc nào.`}</div>`,`<button class="btn" data-close>Hủy</button><button class="btn ${active?'primary':'danger'}" id="confirm-criterion-state">${active?'Khôi phục':'Xác nhận ngừng áp dụng'}</button>`);
 $('#confirm-criterion-state').onclick=async()=>{try{await busyModal(()=>store.updateCriterion({...c,id,active,revision:c.revision||0},criterionIndex));closeModal();render();toast(active?'Đã khôi phục điều kiện.':'Đã ngừng áp dụng. Hồ sơ cũ vẫn được giữ.')}catch(error){err(error)}};
}
async function criterionHistory(id){
 try{const c=criterionIndex.get(id),history=await store.criterionHistory(id),records=Object.values(store.records).filter(r=>r.criterionId===id);modal('Lịch sử · '+e(c.code),`<h3>${e(c.title)}</h3><div class="notice info">${records.length} hồ sơ liên quan · Các phiên bản và tệp đã nộp được giữ nguyên.</div>${records.map(r=>`<button class="btn small" data-history-owner="${e(r.unitId)}">${e(units.find(u=>u.id===r.unitId)?.name)} · Xem hồ sơ</button>`).join('')}<div class="explanation-history">${history.map(h=>`<article class="explanation-message"><strong>${e(h.actor||'Admin')} · ${fmtDate(h.at)}</strong><p>${e(h.before?.title||'Thêm mới')} → ${e(h.after?.title)}</p><small>${h.after?.active===false?'Ngừng áp dụng':`${h.after?.maxScore} điểm · ${e(areaName(h.after?.area))}`}</small></article>`).join('')||'<p class="muted">Chưa có lịch sử chỉnh sửa trong hệ thống.</p>'}</div>`);all('[data-history-owner]').forEach(b=>b.onclick=()=>openCriterion(b.dataset.historyOwner,id))}catch(error){err(error)}
}
function explanations(){
 const rows=Object.values(store.explanations).filter(r=>(admin()||r.unitId===store.user.id)&&(explanationState==='all'||r.status===explanationState)&&(explanationGroup==='all'||units.find(u=>u.id===r.unitId)?.group===explanationGroup)&&matchesArea(criterionIndex.get(r.criterionId))&&`${units.find(u=>u.id===r.unitId)?.name} ${r.criterionCode} ${r.criterionTitle} ${r.reason||''} ${r.lastText}`.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi'))).sort((a,b)=>Number(b.status==='pending')-Number(a.status==='pending')||(b.updatedAt?.toMillis?.()||b.updatedAt||0)-(a.updatedAt?.toMillis?.()||a.updatedAt||0));
 return `${head('Kiến nghị, giải trình',admin()?'Theo dõi lý do nộp muộn, phản hồi và giám sát tiến độ bổ sung của các đơn vị.':'Theo dõi kiến nghị của đơn vị và phản hồi của Tỉnh Đoàn.')}<div class="filters">${admin()?`<select id="explanation-group" aria-label="Khối giải trình"><option value="all">Tất cả khối</option>${options(sets,'name',explanationGroup)}</select>`:''}${areaSelect()}<select id="explanation-state" aria-label="Trạng thái giải trình"><option value="all">Tất cả giải trình</option>${['pending','answered','resolved'].map(status=>`<option value="${status}" ${status===explanationState?'selected':''}>${explanationLabel(status)}</option>`).join('')}</select><div class="search">${icon('search',16)}<input id="search" value="${e(search)}" placeholder="Tìm đơn vị, điều kiện hoặc nội dung giải trình…"></div></div><div class="result-summary"><strong>${rows.length}</strong> kiến nghị, giải trình · <strong>${rows.filter(r=>r.status==='pending').length}</strong> chờ phản hồi</div>${rows.map(r=>`<section class="card explanation-card"><div class="card-head"><div><h2>${e(units.find(u=>u.id===r.unitId)?.name)} · ${e(r.criterionCode)}</h2><small>${e(r.criterionTitle)}</small></div><span class="badge ${r.status==='pending'?'submitted':r.status==='resolved'?'approved':'draft'}">${explanationLabel(r.status)}</span></div><div class="card-body"><p class="explanation-excerpt">${e(r.reason||r.lastText)}</p><div class="explanation-card-foot"><small>Cập nhật: ${fmtDate(r.updatedAt)}${r.expectedDate?` · Dự kiến hoàn thành: ${e(r.expectedDate)}`:''}</small><button class="btn small" data-thread-owner="${e(r.unitId)}" data-thread-criterion="${e(r.criterionId)}">Xem và ${admin()?'phản hồi':'theo dõi'}</button></div></div></section>`).join('')||'<div class="card empty">Chưa có kiến nghị, giải trình phù hợp. Đơn vị mở từng điều kiện trong Minh chứng thi đua để giải trình khi đã khóa hoặc quá hạn nộp.</div>'}`;
}
function explanationSection(u,c){
 if(!admin()&&u.id!==store.user.id)return '';
 const thread=store.explanations[u.id+'__'+c.id],canSend=!admin()&&campaignClosed(store.settings)&&c.active!==false&&!store.settings.resetInProgress,canReply=admin()&&thread&&!store.settings.resetInProgress;
 return `<section class="explanation-panel"><div class="explanation-panel-head"><h3>Kiến nghị, giải trình</h3><span class="badge ${thread?.status==='pending'?'submitted':'draft'}">${explanationLabel(thread?.status)}</span></div>${c.active===false?'<div class="notice">Điều kiện đã ngừng áp dụng. Hồ sơ và lịch sử vẫn được giữ.</div>':''}<p class="muted">Giải trình được lưu riêng với minh chứng, chỉ đơn vị sở hữu và admin được xem. Gửi giải trình không thay đổi điểm hoặc mở lại quyền nộp.</p><div id="explanation-messages" class="explanation-history" aria-live="polite"><p class="muted">Đang đọc lịch sử…</p></div>${canSend||canReply?`<form id="explanation-form"><div class="field"><label for="explanation-text">${admin()?'Phản hồi của Tỉnh Đoàn':'Lý do chưa nộp đúng hạn / kiến nghị của đơn vị'}</label><textarea id="explanation-text" maxlength="4000" required placeholder="${admin()?'Ghi nhận lý do, yêu cầu làm rõ hoặc hướng xử lý…':'Nêu rõ lý do, khó khăn và đề xuất hướng khắc phục…'}"></textarea></div>${admin()?'<div class="field"><label for="explanation-reply-state">Kết quả xử lý</label><select id="explanation-reply-state"><option value="answered">Đã phản hồi · tiếp tục theo dõi</option><option value="resolved">Kết thúc theo dõi giải trình</option></select></div>':'<div class="field"><label for="explanation-date">Ngày dự kiến hoàn thành (nếu có)</label><input id="explanation-date" type="date"></div>'}<button class="btn primary" type="submit">${admin()?'Gửi phản hồi':'Gửi kiến nghị, giải trình'}</button></form>`:!admin()?'<div class="notice info">Mục gửi giải trình được mở khi admin khóa minh chứng hoặc hết hạn nộp.</div>':''}</section>`;
}
function bindExplanation(u,c){
 if(!$('#explanation-messages'))return;
 store.watchExplanation(u.id,c.id,messages=>{const box=$('#explanation-messages');if(!box)return;const latest=messages.at(-1),currentStatus=latest?(latest.role==='admin'?latest.status:'pending'):null,header=$('.explanation-panel-head .badge');if(header){header.textContent=explanationLabel(currentStatus);header.className='badge '+(currentStatus==='pending'?'submitted':currentStatus==='resolved'?'approved':'draft')}box.innerHTML=messages.map(m=>`<article class="explanation-message ${m.role==='admin'?'from-admin':''}"><div><strong>${e(m.actor|| (m.role==='admin'?'Tỉnh Đoàn':u.name))}</strong><small>${fmtDate(m.at)}</small></div><p>${e(m.text)}</p>${m.expectedDate?`<small>Dự kiến hoàn thành: ${e(m.expectedDate)}</small>`:''}${m.status?`<small>${explanationLabel(m.status)}</small>`:''}</article>`).join('')||'<p class="muted">Chưa có kiến nghị, giải trình cho điều kiện này.</p>'},err);
 $('#explanation-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const text=$('#explanation-text'),data={unitId:u.id,criterionId:c.id,text:text.value,revision:store.explanations[u.id+'__'+c.id]?.revision||0,...(admin()?{status:$('#explanation-reply-state').value}:{expectedDate:$('#explanation-date').value})};try{await busyModal(()=>store.postExplanation(data,c,admin()));text.value='';toast(admin()?'Đã gửi phản hồi.':'Đã gửi kiến nghị, giải trình. Hồ sơ minh chứng vẫn giữ nguyên.')}catch(error){err(error)}});
}
function bindManagement(){
 $('#area-filter')?.addEventListener('change',ev=>{areaFilter=ev.target.value;render()});
 $('#manage-group')?.addEventListener('change',ev=>{manageGroup=ev.target.value;render()});
 $('#manage-active')?.addEventListener('change',ev=>{manageActive=ev.target.value;render()});
 $('#explanation-state')?.addEventListener('change',ev=>{explanationState=ev.target.value;render()});
 $('#explanation-group')?.addEventListener('change',ev=>{explanationGroup=ev.target.value;render()});
 $('#add-criterion')?.addEventListener('click',()=>criterionForm());
 all('[data-edit-criterion]').forEach(b=>b.onclick=()=>criterionForm(b.dataset.editCriterion));
 all('[data-toggle-criterion]').forEach(b=>b.onclick=()=>toggleCriterion(b.dataset.toggleCriterion));
 all('[data-criterion-history]').forEach(b=>b.onclick=()=>criterionHistory(b.dataset.criterionHistory));
 all('[data-thread-owner]').forEach(b=>b.onclick=()=>{openCriterion(b.dataset.threadOwner,b.dataset.threadCriterion);$('.explanation-panel')?.scrollIntoView({block:'start',behavior:'smooth'})});
}
